    """Median of the input list xs."""
    n = len(xs)
    if n == 0:
        raise ValueError("List xs must not be empty")
    sorted_xs = sorted(xs)
    mid = n // 2
    if n % 2 == 1:
        return sorted_xs[mid]
    else:
        return (sorted_xs[mid - 1] + sorted_xs[mid]) / 2

def var(xs):
    """Population variance of the input list xs."""
    n = len(xs)
    if n == 0:
        raise ValueError("List xs must not be empty")
    mean = sum(xs) / n
    return sum((x - mean) ** 2 for x in xs) / n

